SELECT 
FROM claim

    deleted = 0
    AND claim_no = #{claimNo}
    AND policy_no = #{policyNo}
    AND insurance_type = #{insuranceType}
    AND status = #{status}
    AND reporter_name LIKE CONCAT('%', #{reporterName}, '%')
    AND reporter_phone = #{reporterPhone}
    AND accident_province = #{accidentProvince}
    AND accident_city = #{accidentCity}
    AND fraud_suspicious = #{fraudSuspicious}
    AND reported_at >= #{reportStartTime}
    AND reported_at <= #{reportEndTime}
    AND accident_time >= #{accidentStartTime}
    AND accident_time <= #{accidentEndTime}
    AND surveyor_id = #{surveyorId}
    AND assessor_id = #{assessorId}
    AND reviewer_id = #{reviewerId}

ORDER BY ${orderBy} ${orderDirection}
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM claim

    deleted = 0
    AND claim_no = #{claimNo}
    AND policy_no = #{policyNo}
    AND insurance_type = #{insuranceType}
    AND status = #{status}
    AND reporter_name LIKE CONCAT('%', #{reporterName}, '%')
    AND reporter_phone = #{reporterPhone}
    AND fraud_suspicious = #{fraudSuspicious}
    AND reported_at >= #{reportStartTime}
    AND reported_at <= #{reportEndTime}
